/*
 * A188729  Decimal expansion of (3+sqrt(109))/10.
 * https://oeis.org/A188729
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, cons
 * Formula:   a(n) = floor((sqrt(109)+3) * 10^(n-2)) mod 10 (n ≥ 2) * a(1) = 1
 *            * The terms are the decimal digits of sqrt(109) after the
 *            decimal point, * starting with the first such digit for n = 3. *
 *            The sequence is generated by digit‑by‑digit extraction of √109
 *            using * high‑precision integer arithmetic impl...
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <string.h>

/* ----------   Small arbitrary‑precision integer   ---------- */

typedef struct {
    uint32_t *d;    /* little‑endian words, base 2^32 */
    size_t   len;   /* number of used words, most significant word non‑zero unless len==0 */
} BigInt;

static void bigint_init(BigInt *a) { a->d = NULL; a->len = 0; }

static void bigint_free(BigInt *a)
{
    free(a->d);
    a->d = NULL;
    a->len = 0;
}

static void bigint_from_uint64(BigInt *a, uint64_t v)
{
    if (v == 0) { a->len = 0; a->d = NULL; return; }
    a->len = (v >> 32) ? 2 : 1;
    a->d = (uint32_t *)malloc(a->len * sizeof(uint32_t));
    a->d[0] = (uint32_t)(v & 0xFFFFFFFF);
    if (a->len == 2) a->d[1] = (uint32_t)(v >> 32);
}

static void bigint_copy(BigInt *dst, const BigInt *src)
{
    dst->len = src->len;
    dst->d = (uint32_t *)malloc(dst->len * sizeof(uint32_t));
    memcpy(dst->d, src->d, dst->len * sizeof(uint32_t));
}

static void bigint_trim(BigInt *a)
{
    while (a->len > 0 && a->d[a->len-1] == 0) a->len--;
}

static void bigint_mul_small(BigInt *a, uint32_t m)
{
    if (m == 0) { bigint_free(a); return; }
    uint64_t carry = 0;
    for (size_t i = 0; i < a->len; ++i) {
        uint64_t prod = (uint64_t)a->d[i] * m + carry;
        a->d[i] = (uint32_t)prod;
        carry    = prod >> 32;
    }
    if (carry) {
        a->d = (uint32_t *)realloc(a->d, (a->len + 1) * sizeof(uint32_t));
        a->d[a->len++] = (uint32_t)carry;
    }
}

static void bigint_add_small(BigInt *a, uint32_t v)
{
    uint64_t sum = (uint64_t)a->d[0] + v;
    a->d[0] = (uint32_t)sum;
    uint32_t carry = (uint32_t)(sum >> 32);
    size_t i = 1;
    while (carry && i < a->len) {
        uint64_t sub = (uint64_t)a->d[i] + carry;
        a->d[i] = (uint32_t)sub;
        carry   = (uint32_t)(sub >> 32);
        i++;
    }
    if (carry) {
        a->d = (uint32_t *)realloc(a->d, (a->len + 1) * sizeof(uint32_t));
        a->d[a->len++] = carry;
    }
}

static void bigint_sub(BigInt *a, const BigInt *b)   /* a >= b */
{
    uint64_t borrow = 0;
    for (size_t i = 0; i < a->len; ++i) {
        uint64_t sub = (uint64_t)a->d[i] - borrow -
                       (i < b->len ? b->d[i] : 0);
        if ((int64_t)sub < 0) {
            sub += ((uint64_t)1 << 32);
            borrow = 1;
        } else
            borrow = 0;
        a->d[i] = (uint32_t)sub;
    }
    bigint_trim(a);
}

static int bigint_cmp(const BigInt *a, const BigInt *b)
{
    if (a->len != b->len) return (a->len < b->len) ? -1 : 1;
    for (size_t i = a->len; i-- > 0;) {
        if (a->d[i] != b->d[i]) return (a->d[i] < b->d[i]) ? -1 : 1;
    }
    return 0;
}

/* ----------   Digit generation for √109   ---------- */

static BigInt root_si, rem_si;              /* current root and remainder   */
static uint8_t *digits = NULL;              /* cached decimal digits of √109      */
static size_t   digits_cap = 0;
static size_t   digits_len = 0;
static int      cache_initialized = 0;

/* Force generation of at least n digits (n ≤ any requested index) */
static void ensure_digits(size_t n)
{
    if (digits_len >= n) return;

    /* initialize root = 10, remainder = 109 – 10² = 9 */
    if (!cache_initialized) {
        bigint_from_uint64(&root_si, 10);
        bigint_from_uint64(&rem_si, 9);
        cache_initialized = 1;
    }

    /* generate digits until we reach n */
    while (digits_len < n) {
        /* remainder *= 100 */
        bigint_mul_small(&rem_si, 100);

        /* determine next decimal digit */
        int d_sel = 0;
        for (int d = 9; d >= 0; --d) {
            BigInt tmp;
            bigint_copy(&tmp, &root_si);
            bigint_mul_small(&tmp, 20);          /* 20*root   */
            bigint_add_small(&tmp, (uint32_t)d); /* + d       */
            bigint_mul_small(&tmp, (uint32_t)d); /* * d       */
            if (bigint_cmp(&tmp, &rem_si) <= 0) {
                d_sel = d;
                bigint_free(&tmp);
                break;
            }
            bigint_free(&tmp);
        }

        /* compute the chosen candidate just once more */
        BigInt cand;
        bigint_copy(&cand, &root_si);
        bigint_mul_small(&cand, 20);
        bigint_add_small(&cand, (uint32_t)d_sel);
        bigint_mul_small(&cand, (uint32_t)d_sel);

        /* rem -= candidate */
        bigint_sub(&rem_si, &cand);
        bigint_free(&cand);

        /* root = root*10 + d_sel */
        bigint_mul_small(&root_si, 10);
        bigint_add_small(&root_si, (uint32_t)d_sel);

        /* store the digit */
        if (digits_len == digits_cap) {
            size_t newcap = digits_cap ? digits_cap * 2 : 16;
            uint8_t *newptr = (uint8_t *)realloc(digits, newcap);
            if (!newptr) abort();
            digits = newptr;
            digits_cap = newcap;
        }
        digits[digits_len++] = (uint8_t)d_sel;
    }
}

/* ----------   Sequence function   ---------- */

seq_t a(idx_t n)
{
    if (n == 1) return (seq_t)1;
    if (n == 2) return (seq_t)3;

    /* a(n) for n>=3 is the (n-3)‑th cached digit (0‑based)          */
    size_t need = n - 2;                 /* number of digits that must exist   */
    ensure_digits(need);

    return (seq_t)digits[n - 3];         /* a(3) -> digits[0] = 4, etc.       */
}
